        clauses.min { lhs, rhs in
            let ldx = lhs.x - point.x
            let ldy = lhs.y - point.y
            let rdx = rhs.x - point.x
            let rdy = rhs.y - point.y
            return ldx * ldx + ldy * ldy < rdx * rdx + rdy * rdy
        } ?? point
    }

