        if let account = auth?.account {
            diagnostics["accountPresent"] = "true"
            if let environment = account.environment { diagnostics["accountEnvironment"] = environment }
        } else {
            diagnostics["accountPresent"] = "false"
        }
        return diagnostics
    }

