    private static func extractPDFText(url: URL) throws -> String {
        guard let pdf = PDFDocument(url: url) else {
            throw FileExtractionError.pdfOpenFailed
        }
        var combined = ""
        for i in 0..<pdf.pageCount {
            combined += pdf.page(at: i)?.string ?? ""
            combined += "\n\n"
        }
        return combined
    }

