                prompt: prompt,
                intent: routing.intent,
                hasAttachments: !req.attachments.isEmpty,
                hasRelevantMemories: !req.relevantMemories.isEmpty
            ) != nil
        }

        guard IntentRouter.intentRequiresTool(routing) else { return false }

