    var body: some View {
        if !payloads.isEmpty {
            VStack(alignment: .leading, spacing: 10) {
                ForEach(Array(payloads.enumerated()), id: \.offset) { _, payload in
                    WebRichPayloadCard(payload: payload)
                }
