        private let loadsChatOnReadiness: Bool
        private(set) var readinessCallCount = 0
        private(set) var preflightCallCount = 0
        private(set) var streamCallCount = 0
        private(set) var callOrder: [String] = []

        init(
            isChatLoaded: Bool,
            scripts: [[GenerationToken]],
