final class RAGSearchToolTests: XCTestCase {
    func testExplicitRAGSourceOwnershipOutranksGenericQueryTerms() {
        XCTAssertEqual(
            RAGSourceScope.inferred(fromUserPrompt: "Search my files for architecture notes."),
            .documents
        )
