            toolID: "mail.draft",
            toolArgs: [
                "to": "sam@example.com",
                "subject": "Timeline",
                "body": "Status green"
            ]
        )

        guard let message = ChatApprovalBoundaryMapper.pendingToolMessage(for: step) else {
