def repo_relative(path: pathlib.Path) -> str:
    return path.resolve().relative_to(REPO_ROOT).as_posix()


def iter_swift_files(roots: list[pathlib.Path]):
    for root in roots:
        if root.is_file() and root.suffix == ".swift":
            yield root
        elif root.exists():
            yield from root.rglob("*.swift")


