def _dedupe_runtime_reports(reports: list[dict[str, Any]]) -> list[dict[str, Any]]:
    deduped: list[dict[str, Any]] = []
    report_indexes: dict[str, int] = {}
    for report in reports:
        report_id = _stable_report_id(report)
