def argument_value(block: str, label: str) -> str | None:
    match = re.search(rf"\b{re.escape(label)}\s*:\s*", block)
    if not match:
        return None

    start = match.end()
    depth = 0
    in_string = False
    escaped = False
    end = start
    while end < len(block):
        ch = block[end]
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
        else:
            if ch == '"':
                in_string = True
            elif ch in "([{":
                depth += 1
            elif ch in ")]}" and depth > 0:
                depth -= 1
            elif depth == 0 and ch in ",\n)":
                break
        end += 1

    value = block[start:end].strip()
    return value or None


def bool_value(raw: str | None, default: bool = False) -> bool:
    if raw is None:
        return default
    token = raw.strip().strip(",)").lower()
    if token in {"true", ".true"}:
        return True
    if token in {"false", ".false"}:
        return False
    return default


def clean_swift_string(raw: str | None) -> str | None:
    if not raw:
        return None
    raw = raw.strip().strip(",")
    if raw in {"nil", "NULL", "Null", "null", "Optional.none", ".none"}:
        return None
    if raw.startswith('"') and raw.endswith('"'):
        return raw[1:-1]
    if raw.startswith("."):
        return raw[1:]
    return raw

