def _validate_natural_intent_tool_leaks(*, agent: str, ds: Any, failures: list[ValidationFailure], known_tools: set[str]) -> None:  # NOSONAR
    for index, rec in enumerate(ds.eval):
        metadata = rec.get("metadata")
